// Generates packages/contracts/schemas/*.v1.schema.json (JSON Schema draft 2020-12) from the TypeScript
// enum arrays in packages/contracts/src/enums.ts, so enums have exactly one source. The generated files are
// committed; unit tests cross-check them (Ajv, test-only) against the hand-written runtime validator.
// Usage: node scripts/gen-schemas.mjs [--check]   (--check exits 1 when committed files differ)

import { build } from 'esbuild';
import { mkdirSync, readFileSync, writeFileSync, existsSync } from 'node:fs';
import { dirname, join, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

const root = resolve(dirname(fileURLToPath(import.meta.url)), '..');
const outDir = join(root, 'packages', 'contracts', 'schemas');
const checkOnly = process.argv.includes('--check');

const bundled = await build({
  entryPoints: [join(root, 'packages', 'contracts', 'src', 'enums.ts')],
  bundle: true,
  format: 'esm',
  platform: 'neutral',
  write: false,
  logLevel: 'silent',
});
const enums = await import('data:text/javascript;base64,' + Buffer.from(bundled.outputFiles[0].text).toString('base64'));
const budgetsBundle = await build({
  entryPoints: [join(root, 'packages', 'contracts', 'src', 'budgets.ts')],
  bundle: true,
  format: 'esm',
  platform: 'neutral',
  write: false,
  logLevel: 'silent',
});
const { BUDGETS, MAX_COUNT } = await import(
  'data:text/javascript;base64,' + Buffer.from(budgetsBundle.outputFiles[0].text).toString('base64')
);

const DRAFT = 'https://json-schema.org/draft/2020-12/schema';
// RFC 8141 NID: letters, digits, hyphen only (no dots), hence "detect-expert".
const URN = (name) => 'urn:detect-expert:contracts:' + name + ':v1';
const ref = (def) => ({ $ref: URN('common') + '#/$defs/' + def });
const MAX_TS = Number.MAX_SAFE_INTEGER;

const ID_PATTERN = '^[A-Za-z0-9_-]+$';
const DOCUMENT_KEY_PATTERN = '^[A-Za-z0-9_:.-]+$';
const HOST_PATTERN =
  '^(?:(?:[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?)(?:\\.[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?)*|\\[[0-9a-f:.]{2,45}\\])$';

const enumDef = (values, description) => ({ type: 'string', enum: [...values], description });
const enumArray = (def, maxItems) => ({ type: 'array', maxItems, uniqueItems: true, items: ref(def) });
const obj = (properties, required = Object.keys(properties)) => ({
  type: 'object',
  additionalProperties: false,
  required,
  properties,
});
const boundedStringArray = (maxItems) => ({
  type: 'array',
  maxItems,
  items: { type: 'string', minLength: 1, maxLength: BUDGETS.maxStringChars },
});

const common = {
  $schema: DRAFT,
  $id: URN('common'),
  title: 'detect.expert protocol v1 — shared definitions',
  description: 'Canonical enums and shared objects. Generated by scripts/gen-schemas.mjs from packages/contracts/src.',
  $defs: {
    techniqueId: enumDef(enums.TECHNIQUE_IDS, 'Technique registry id DET-001..DET-069.'),
    signalCode: enumDef(enums.SIGNAL_CODES, 'Allowed enumerated signal codes; never free-form strings.'),
    coverageFlag: enumDef(enums.COVERAGE_FLAGS, 'Why observation coverage is incomplete.'),
    evidenceSource: enumDef(enums.EVIDENCE_SOURCES),
    integrity: enumDef(enums.INTEGRITIES),
    interpretation: enumDef(enums.INTERPRETATIONS),
    interpretationConfidence: enumDef(enums.INTERPRETATION_CONFIDENCES),
    attributionConfidence: enumDef(enums.ATTRIBUTION_CONFIDENCES),
    vendorConfidence: enumDef(enums.VENDOR_MATCHES),
    coverageState: enumDef(enums.COVERAGE_STATES),
    countQuality: enumDef(enums.COUNT_QUALITIES),
    phase: enumDef(enums.PHASES),
    scopeMode: enumDef(enums.SCOPE_MODES),
    sensorState: enumDef(enums.SENSOR_STATES),
    bridgeStopReason: enumDef(enums.BRIDGE_STOP_REASONS),
    bridgeControlCommand: enumDef(enums.BRIDGE_CONTROL_COMMANDS, 'SW -> bridge control commands (tabs.sendMessage).'),
    documentLifecycle: enumDef(enums.DOCUMENT_LIFECYCLES),
    uiErrorCode: enumDef(enums.UI_ERROR_CODES),
    channel: { const: enums.CHANNEL },
    schemaVersion: { const: enums.PROTOCOL_VERSION },
    id: { type: 'string', minLength: 1, maxLength: BUDGETS.maxIdChars, pattern: ID_PATTERN },
    documentKey: { type: 'string', minLength: 1, maxLength: BUDGETS.maxDocumentKeyChars, pattern: DOCUMENT_KEY_PATTERN },
    host: { type: 'string', minLength: 1, maxLength: 253, pattern: HOST_PATTERN },
    count: {
      type: 'integer',
      minimum: 0,
      maximum: MAX_COUNT,
      description: 'Saturating counter. The runtime validator saturates larger finite integers to the maximum.',
    },
    seq: { type: 'integer', minimum: 1, maximum: MAX_COUNT },
    nonNegInt: { type: 'integer', minimum: 0, maximum: MAX_COUNT },
    timestampMs: { type: 'integer', minimum: 0, maximum: MAX_TS },
    coverageFlags: enumArray('coverageFlag', enums.COVERAGE_FLAGS.length),
    pageObservation: obj({
      techniqueId: ref('techniqueId'),
      count: ref('count'),
      countQuality: ref('countQuality'),
      phase: ref('phase'),
      signalCodes: enumArray('signalCode', BUDGETS.maxSignalCodesPerObservation),
      intervalBucket: ref('nonNegInt'),
    }),
    observations: {
      type: 'array',
      minItems: 1,
      maxItems: BUDGETS.maxBatchEvents,
      items: ref('pageObservation'),
    },
    droppedCounters: obj({
      observations: ref('count'),
      batches: ref('count'),
      findings: ref('count'),
      hosts: ref('count'),
      counters: ref('count'),
      transport: ref('count'),
      ring: ref('count'),
    }, ['observations', 'batches', 'findings', 'hosts', 'counters', 'transport']),
    finding: {
      ...obj(
        {
          findingId: ref('id'),
          ruleId: ref('id'),
          ruleVersion: { type: 'string', minLength: 1, maxLength: BUDGETS.maxIdChars },
          techniqueId: ref('techniqueId'),
          interpretation: ref('interpretation'),
          interpretationConfidence: ref('interpretationConfidence'),
          evidenceIds: boundedStringArray(64),
          counterEvidenceCodes: boundedStringArray(32),
          limitationCodes: boundedStringArray(32),
          vendorMatchIds: boundedStringArray(32),
          coverageRef: ref('id'),
        },
        [
          'findingId',
          'ruleId',
          'ruleVersion',
          'techniqueId',
          'interpretation',
          'interpretationConfidence',
          'evidenceIds',
          'counterEvidenceCodes',
          'limitationCodes',
          'vendorMatchIds',
        ],
      ),
    },
    techniqueSummary: obj({
      techniqueId: ref('techniqueId'),
      count: ref('count'),
      countQuality: ref('countQuality'),
      phases: enumArray('phase', enums.PHASES.length),
      signalCodes: enumArray('signalCode', enums.SIGNAL_CODES.length),
      evidenceSource: ref('evidenceSource'),
      integrity: ref('integrity'),
      interpretation: ref('interpretation'),
      interpretationConfidence: ref('interpretationConfidence'),
      attributionConfidence: ref('attributionConfidence'),
      firstBucket: ref('nonNegInt'),
      lastBucket: ref('nonNegInt'),
    }),
    vendorSummary: obj({
      vendorId: ref('id'),
      vendorConfidence: ref('vendorConfidence'),
      ruleIds: boundedStringArray(32),
      evidenceSource: ref('evidenceSource'),
      integrity: ref('integrity'),
    }),
    reportProjection: obj({
      reportRevision: ref('nonNegInt'),
      documentKey: ref('documentKey'),
      host: { anyOf: [ref('host'), { type: 'null' }] },
      coverageState: ref('coverageState'),
      coverageFlags: ref('coverageFlags'),
      techniques: { type: 'array', maxItems: BUDGETS.maxCountersPerDocumentGroup, items: ref('techniqueSummary') },
      findings: { type: 'array', maxItems: BUDGETS.maxFindingsPerDocument, items: ref('finding') },
      vendors: { type: 'array', maxItems: BUDGETS.maxHostsPerDocument, items: ref('vendorSummary') },
      dropped: ref('droppedCounters'),
      observedSince: { anyOf: [ref('timestampMs'), { type: 'null' }] },
      scopeMode: ref('scopeMode'),
    }),
    scopeState: obj({
      scopeMode: ref('scopeMode'),
      hosts: { type: 'array', maxItems: BUDGETS.maxHostsPerDocument, uniqueItems: true, items: ref('host') },
      grantedAllSites: { type: 'boolean' },
      managed: { type: 'boolean' },
    }),
    exportReport: obj({
      host: { anyOf: [ref('host'), { type: 'null' }] },
      coverageState: ref('coverageState'), coverageFlags: ref('coverageFlags'),
      techniques: { type: 'array', maxItems: BUDGETS.maxCountersPerDocumentGroup, items: ref('techniqueSummary') },
      findings: { type: 'array', maxItems: BUDGETS.maxFindingsPerDocument, items: ref('finding') },
      vendors: { type: 'array', maxItems: BUDGETS.maxHostsPerDocument, items: ref('vendorSummary') },
      dropped: ref('droppedCounters'),
      observationAgeMinutes: { anyOf: [ref('nonNegInt'), { type: 'null' }] },
      scopeMode: ref('scopeMode'),
    }),
    exportPreview: obj({
      schemaVersion: ref('schemaVersion'), redacted: { const: true },
      documentOrdinal: { type: 'integer', minimum: 1, maximum: 1 },
      reportRevision: ref('nonNegInt'), report: ref('exportReport'),
    }),
    counterEntry: obj({
      techniqueId: ref('techniqueId'),
      phase: ref('phase'),
      signalCodes: enumArray('signalCode', BUDGETS.maxSignalCodesPerObservation),
      count: ref('count'),
      countQuality: ref('countQuality'),
      firstBucket: ref('nonNegInt'),
      lastBucket: ref('nonNegInt'),
    }),
    hostEntry: { ...obj({
      registrableDomain: ref('host'),
      category: { enum: ['loopback', 'link-local', 'private', 'ULA', 'public', 'localhost', 'local', 'single-label', 'unknown'] },
      relation: { enum: ['same-origin', 'same-site', 'cross-site', 'opaque', 'unknown'] },
      evidenceSource: { const: 'browser-network' },
      integrity: { const: 'browser-observed' },
      requestCount: ref('count'),
      firstSeenBucket: ref('nonNegInt'),
      lastSeenBucket: ref('nonNegInt'),
      ruleIds: boundedStringArray(32),
    }, ['relation', 'evidenceSource', 'integrity', 'requestCount', 'firstSeenBucket', 'lastSeenBucket', 'ruleIds']),
      oneOf: [{ properties: { registrableDomain: {} }, required: ['registrableDomain'] }, { properties: { category: {} }, required: ['category'] }],
    },
    dedupWatermark: obj({
      bridgeSessionId: ref('id'),
      lastCommittedBatchSeq: ref('nonNegInt'),
    }),
  },
};

// A PageBatch may carry no observations only as a coverage-only batch (non-empty coverageDelta): the bridge
// reports sensor diagnostics (protocol mismatch, hook failure, pause) without fabricating an observation
// (ADR-004 changelog, F033/F034). A MAIN -> ISOLATED sensor-batch still needs >= 1 observation.
const pageBatch = {
  $schema: DRAFT,
  $id: URN('page-batch'),
  title: 'PageBatch v1 — ISOLATED -> service worker; untrusted input',
  ...obj({
    schemaVersion: ref('schemaVersion'),
    type: { const: 'sensor-events' },
    sensorBootId: ref('id'),
    bridgeSessionId: ref('id'),
    batchSeq: ref('seq'),
    observations: { type: 'array', maxItems: BUDGETS.maxBatchEvents, items: ref('pageObservation') },
    coverageDelta: ref('coverageFlags'),
  }),
  anyOf: [
    { type: 'object', properties: { observations: { type: 'array', minItems: 1 } } },
    { type: 'object', properties: { coverageDelta: { type: 'array', minItems: 1 } } },
  ],
};

const ack = {
  $schema: DRAFT,
  $id: URN('ack'),
  title: 'Ack v1 — service worker -> ISOLATED, sent after snapshot + watermark are persisted',
  ...obj({
    schemaVersion: ref('schemaVersion'),
    type: { const: 'ack' },
    lastCommittedBatchSeq: ref('nonNegInt'),
    paused: { type: 'boolean' },
    protocolOk: { type: 'boolean' },
    stopReason: { const: 'revoked' },
  }, ['schemaVersion', 'type', 'lastCommittedBatchSeq', 'paused', 'protocolOk']),
};

const pageHeader = { channel: ref('channel'), sensorBootId: ref('id') };
const pageMessage = {
  $schema: DRAFT,
  $id: URN('page-message'),
  title: 'PageMessage v1 — MAIN <-> ISOLATED window.postMessage payloads; page-controlled',
  oneOf: [
    obj({
      ...pageHeader,
      type: { const: 'sensor-hello' },
      protocolVersion: ref('nonNegInt'),
      startedLate: { type: 'boolean' },
      coverageFlags: ref('coverageFlags'),
    }),
    obj({
      ...pageHeader,
      type: { const: 'sensor-batch' },
      sensorSeq: ref('seq'),
      observations: ref('observations'),
      coverageDelta: ref('coverageFlags'),
    }),
    obj({
      ...pageHeader,
      type: { const: 'sensor-status' },
      state: ref('sensorState'),
      coverageFlags: ref('coverageFlags'),
      droppedSinceLast: ref('count'),
    }),
    obj({
      ...pageHeader,
      type: { const: 'bridge-hello' },
      protocolVersion: ref('nonNegInt'),
      bridgeSessionId: ref('id'),
      paused: { type: 'boolean' },
    }),
    obj({ ...pageHeader, type: { const: 'bridge-pause' } }),
    obj({ ...pageHeader, type: { const: 'bridge-resume' } }),
    obj({ ...pageHeader, type: { const: 'bridge-stop' }, reason: ref('bridgeStopReason') }),
    obj({ ...pageHeader, type: { const: 'bridge-reset' }, resetId: ref('id') }),
    obj({ ...pageHeader, type: { const: 'sensor-reset' }, resetId: ref('id'), nextSensorBootId: ref('id'), coverageFlags: ref('coverageFlags') }),
  ],
};

const bridgeControl = {
  $schema: DRAFT,
  $id: URN('bridge-control'),
  title: 'BridgeControl v1 - service worker -> ISOLATED bridge (chrome.tabs.sendMessage to one document)',
  oneOf: [
    obj({ schemaVersion: ref('schemaVersion'), type: { const: 'bridge-control' }, command: { enum: ['pause', 'resume', 'stop'] } }),
    obj({ schemaVersion: ref('schemaVersion'), type: { const: 'bridge-control' }, command: { const: 'reset' }, resetId: ref('id') }),
  ],
};

const bridgeResetAck = { $schema: DRAFT, $id: URN('bridge-reset-ack'), ...obj({
  schemaVersion: ref('schemaVersion'), type: { const: 'bridge-reset-ack' }, resetId: ref('id'), bridgeSessionId: ref('id'),
  sensorBootIds: { type: 'array', minItems: 1, maxItems: 4, uniqueItems: true, items: ref('id') },
}) };

const uiBase = { schemaVersion: ref('schemaVersion') };
const revisionRequest = (type) =>
  obj({
    ...uiBase,
    type: { const: type },
    tabId: ref('nonNegInt'),
    documentKey: ref('documentKey'),
    reportRevision: ref('nonNegInt'),
  });
const uiRequest = {
  $schema: DRAFT,
  $id: URN('ui-request'),
  title: 'UiRequest v1 — extension UI pages -> service worker (privileged channel; sender verified separately)',
  oneOf: [
    obj({ ...uiBase, type: { const: 'ui-get-report' }, tabId: ref('nonNegInt'), frameId: { type: 'integer', minimum: 0, maximum: Number.MAX_SAFE_INTEGER } }, [
      'schemaVersion',
      'type',
      'tabId',
    ]),
    revisionRequest('ui-pause'),
    revisionRequest('ui-resume'),
    revisionRequest('ui-clear'),
    obj({ ...uiBase, type: { const: 'ui-set-scope' }, scopeMode: { const: 'site' }, host: ref('host') }),
    obj({
      ...uiBase,
      type: { const: 'ui-set-scope' },
      scopeMode: { type: 'string', enum: enums.SCOPE_MODES.filter((m) => m !== 'site') },
    }),
    obj({ ...revisionRequest('ui-export-preview').properties, includeHost: { type: 'boolean' } }, revisionRequest('ui-export-preview').required),
    obj({ ...uiBase, type: { const: 'ui-get-scope' } }),
    obj({ ...uiBase, type: { const: 'ui-inject-now' }, tabId: ref('nonNegInt') }),
    obj({ ...uiBase, type: { const: 'ui-clear-session' } }),
  ],
};

const uiResponse = {
  $schema: DRAFT,
  $id: URN('ui-response'),
  title: 'UiResponse v1 — service worker -> extension UI pages',
  oneOf: [
    obj({ ...uiBase, type: { const: 'report' }, report: { anyOf: [ref('reportProjection'), { type: 'null' }] } }),
    obj({ ...uiBase, type: { const: 'ok' }, reportRevision: { anyOf: [ref('nonNegInt'), { type: 'null' }] } }),
    obj({ ...uiBase, type: { const: 'scope' }, scope: ref('scopeState') }),
    obj({ ...uiBase, type: { const: 'export-preview' }, preview: ref('exportPreview') }),
    obj({ ...uiBase, type: { const: 'error' }, code: ref('uiErrorCode') }),
  ],
};

const reportProjection = {
  $schema: DRAFT,
  $id: URN('report-projection'),
  title: 'ReportProjection v1 — read-only view bound to reportRevision',
  ...ref('reportProjection'),
};

const documentReport = {
  $schema: DRAFT,
  $id: URN('document-report'),
  title: 'DocumentReport v1 — stored per documentId in storage.session; the service worker is the only writer',
  ...obj({
    schemaVersion: ref('schemaVersion'),
    documentKey: ref('documentKey'),
    tabId: ref('nonNegInt'),
    frameId: ref('nonNegInt'),
    documentId: ref('id'),
    host: { anyOf: [ref('host'), { type: 'null' }] },
    lifecycle: ref('documentLifecycle'),
    createdAt: ref('timestampMs'),
    updatedAt: ref('timestampMs'),
    revision: ref('nonNegInt'),
    coverageState: ref('coverageState'),
    coverageFlags: ref('coverageFlags'),
    counters: { type: 'array', maxItems: BUDGETS.maxCountersPerDocumentGroup, items: ref('counterEntry') },
    findings: { type: 'array', maxItems: BUDGETS.maxFindingsPerDocument, items: ref('finding') },
    hosts: { type: 'array', maxItems: BUDGETS.maxHostsPerDocument, items: ref('hostEntry') },
    watermark: { anyOf: [ref('dedupWatermark'), { type: 'null' }] },
    dropped: ref('droppedCounters'),
  }),
};

const files = {
  'common.v1.schema.json': common,
  'page-batch.v1.schema.json': pageBatch,
  'ack.v1.schema.json': ack,
  'page-message.v1.schema.json': pageMessage,
  'bridge-control.v1.schema.json': bridgeControl,
  'bridge-reset-ack.v1.schema.json': bridgeResetAck,
  'ui-request.v1.schema.json': uiRequest,
  'ui-response.v1.schema.json': uiResponse,
  'report-projection.v1.schema.json': reportProjection,
  'document-report.v1.schema.json': documentReport,
};

mkdirSync(outDir, { recursive: true });
let drift = 0;
for (const [name, schema] of Object.entries(files)) {
  const text = JSON.stringify(schema, null, 2) + '\n';
  const target = join(outDir, name);
  if (checkOnly) {
    const current = existsSync(target) ? readFileSync(target, 'utf8') : '';
    if (current !== text) {
      drift++;
      console.error('schema drift: ' + name);
    }
  } else {
    writeFileSync(target, text);
    console.log('wrote ' + name + ' (' + text.length + ' bytes)');
  }
}
if (checkOnly) {
  if (drift > 0) {
    console.error(drift + ' schema file(s) out of date; run node scripts/gen-schemas.mjs');
    process.exit(1);
  }
  console.log('schemas up to date');
}
